"""Styles for the local living-brand workshop."""

# Static CSS is kept as one dependency-free asset.
# ruff: noqa: E501

WORKSHOP_CSS = """
:root{--paper:#f4f0e7;--surface:#fffdf7;--ink:#17201c;--muted:#526058;--accent:#b83b27;--line:#aaa99f}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font:1rem/1.55 system-ui,sans-serif}header,main{width:min(72rem,calc(100% - 2rem));margin:auto}header{display:flex;justify-content:space-between;padding:1.25rem 0;border-bottom:1px solid var(--line)}nav{display:flex;gap:1rem}a{color:inherit;text-underline-offset:.2em}.skip-link{position:fixed;transform:translateY(-200%);background:var(--ink);color:white;padding:.75rem}.skip-link:focus{transform:none}main{padding:3rem 0}.intro{max-width:44rem}.eyebrow{text-transform:uppercase;font-weight:800;letter-spacing:.12em;color:var(--accent)}h1{font:500 clamp(2.5rem,7vw,5rem)/1 Georgia,serif}form{display:grid;gap:.75rem;padding:1.5rem;background:var(--surface);border:2px solid var(--ink)}input,textarea,select,button{font:inherit;padding:.75rem;border:2px solid var(--ink);background:var(--surface);color:var(--ink)}button{cursor:pointer;background:var(--accent);color:white;font-weight:800}.workspace-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1rem}.workspace-card{padding:1rem;background:var(--surface);border:1px solid var(--line)}.workshop-grid{display:grid;grid-template-columns:18rem 1fr;gap:2rem}#section-navigation{display:grid;align-content:start}#section-navigation button{text-align:left;background:var(--surface);color:var(--ink)}.field-help{margin:.15rem 0 .6rem;font-size:.85rem;color:var(--muted);max-width:60ch}.field-help code{background:var(--paper);padding:.05rem .3rem;border:1px solid var(--line)}.block-editor,.item-editor{display:grid;gap:.5rem}.item-editor{padding:1rem;border:1px solid var(--line);background:var(--paper)}#section-form h3{margin:1.25rem 0 0;font:600 1.1rem/1.2 Georgia,serif}#section-form label{display:grid;gap:.25rem}.subgroup{display:grid;gap:.5rem;padding:.75rem;border-left:3px solid var(--line)}.subgroup>p{margin:0;font-weight:800;text-transform:uppercase;font-size:.75rem;letter-spacing:.06em;color:var(--muted)}.spec-row{display:grid;gap:.5rem}button.remove{background:var(--surface);color:var(--ink);justify-self:start;padding:.4rem .75rem}textarea{min-height:8rem;resize:vertical}.item-editor textarea{min-height:4rem}.asset-panel{margin-top:2rem}#asset-list{margin:0 0 1rem;padding-left:1.25rem;display:grid;gap:.35rem}#asset-list li{overflow-wrap:anywhere}.asset-required{display:flex;align-items:center;gap:.5rem}.asset-required input{width:auto;padding:0}input[type=file]{padding:.5rem;background:var(--paper)}:focus-visible{outline:3px solid var(--accent);outline-offset:3px}@media (max-width: 48rem){header,.workshop-grid{display:grid;grid-template-columns:1fr}.workspace-grid{grid-template-columns:1fr}#section-navigation{position:static}}@media (prefers-reduced-motion: reduce){*{scroll-behavior:auto!important;transition:none!important}}
"""
